const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const clock=t=>new Date(t).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});const names={QUEUED:'À préparer',PREPARING:'En préparation',BAKING:'Au four',READY:'Prête',COLLECTED:'Retirée',CANCELLED:'Annulée'};let page='dashboard',filter='all',cart={},selected=0,state;const KEY='click-eat-demo-v1';const recipes=[{id:'marg',name:'Margherita',desc:'Tomate San Marzano, mozzarella fior di latte, basilic frais.',price:11,bom:{dough:1,tomato:100,mozza:100,box:1},tag:'La grande classique'},{id:'regina',name:'Regina',desc:'Tomate, mozzarella, jambon blanc, champignons frais.',price:14,bom:{dough:1,tomato:100,mozza:100,ham:80,mushroom:60,box:1},tag:'La préférée du quartier'},{id:'burrata',name:'Burrata',desc:'Tomate, burrata crémeuse, roquette et huile d’olive.',price:16,bom:{dough:1,tomato:100,burrata:1,box:1},tag:'La généreuse'},{id:'quattro',name:'Quattro formaggi',desc:'Mozzarella, gorgonzola, chèvre et parmesan.',price:15,bom:{dough:1,mozza:100,cheese:100,box:1},tag:'Pour les amateurs de fromage'}];
function initial(){const now=Date.now(),base=Math.ceil((now+12*60000)/600000)*600000;return{slots:Array.from({length:8},(_,i)=>base+i*600000),capacity:50,pausedUntil:0,stock:{dough:{name:'Pâtons',qty:420,unit:'pièces',alert:50},tomato:{name:'Sauce tomate',qty:19000,unit:'g',alert:2000},mozza:{name:'Mozzarella',qty:14000,unit:'g',alert:2000},ham:{name:'Jambon blanc',qty:6000,unit:'g',alert:1000},mushroom:{name:'Champignons',qty:2800,unit:'g',alert:3000},burrata:{name:'Burrata',qty:8,unit:'pièces',alert:12},cheese:{name:'Mélange fromages',qty:6500,unit:'g',alert:1000},box:{name:'Boîtes à pizza',qty:480,unit:'pièces',alert:100}},orders:[{id:1042,name:'Camille D.',items:{regina:2,marg:1},slot:base,status:'PREPARING'},{id:1043,name:'Thomas L.',items:{burrata:2},slot:base,status:'BAKING',bakedAt:now-180000},{id:1044,name:'Sarah M.',items:{quattro:1,marg:1},slot:base,status:'READY'},{id:1045,name:'Lucas B.',items:{regina:3},slot:base,status:'QUEUED'},{id:1046,name:'Emma R.',items:{marg:2,burrata:1},slot:base+600000,status:'QUEUED'},{id:1047,name:'Hugo P.',items:{quattro:2},slot:base+600000,status:'QUEUED'}],hold:null,notifications:[],next:1048}}
state=initial();state.orders=[];function save(){}function qty(items){return Object.values(items).reduce((a,b)=>a+b,0)}function total(items){return recipes.reduce((n,r)=>n+r.price*(items[r.id]||0),0)}function need(items){let out={};recipes.forEach(r=>Object.entries(r.bom).forEach(([id,n])=>out[id]=(out[id]||0)+n*(items[r.id]||0)));return out}function held(){return state.hold&&state.hold.expires>Date.now()?state.hold:null}function enough(items,includeHold=true){const use=need(items),reserved=includeHold&&held()?need(state.hold.items):{};return Object.entries(use).every(([id,n])=>n<=(state.stock[id].qty-(reserved[id]||0)-(state.reservedOther?.[id]||0)))}function load(slot){return state.orders.filter(o=>o.slot===slot&&o.status!=='CANCELLED').reduce((n,o)=>n+qty(o.items),0)+(held()?.slot===slot?qty(state.hold.items):0)+(state.slotHolds?.[slot]||0)}function paused(){return state.pausedUntil>Date.now()}function expire(){if(state.hold&&state.hold.expires<=Date.now()){state.hold=null;save();$('#modal').close();toast('Réservation expirée. Le créneau et les ingrédients ont été libérés.');render()}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',4200)}function nav(p){page=p;render()}const itemtext=items=>recipes.filter(r=>items[r.id]).map(r=>`${items[r.id]} × ${r.name}`).join(', ');function badge(o){return `<span class="badge ${o.status}">${names[o.status]}</span>`}
function render(){const active=state.orders.filter(o=>!['COLLECTED','CANCELLED'].includes(o.status));const titles={dashboard:'Vue d’ensemble',kitchen:'Écran cuisine',orders:'Commandes',stock:'Stocks & recettes',capacity:'Capacité & service',client:'Boutique client'};$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span>c.</span><div>click<em>eat</em></div></div><div class="restaurant">La Fabrique à Pizza <small>Établissement principal⌄</small></div><div class="navlabel">PILOTAGE</div><nav class="nav">${[['dashboard','◫','Vue d’ensemble'],['orders','▤','Commandes'],['kitchen','♨','Écran cuisine'],['stock','▦','Stocks & recettes'],['capacity','◷','Capacité & service'],['client','↗','Boutique client']].map(([p,i,t])=>`<button title="${t}" class="${page===p?'active':''}" data-nav="${p}"><span class="icon">${i}</span><span>${t}</span>${p==='orders'?`<span class="count">${active.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><span class="avatar">AL</span>Alex · Manager<br><br>Serveur connecté<br>Base de données partagée</div></aside><div class="shell"><header class="topbar"><div class="crumb">Espace pizzeria <span style="margin:0 12px;color:#c4c9c4">/</span> <strong>${titles[page]}</strong></div><div class="top-right"><span class="date">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</span><span class="live">${navigator.onLine?'Serveur partagé':'Hors connexion'}</span><span class="avatar">AL</span></div></header><main>${page==='dashboard'?dashboard():page==='orders'?ordersView():page==='kitchen'?kitchen():page==='stock'?stocks():page==='capacity'?capacityView():client()}<footer class="footnote"><span>Click Eat · La Fabrique à Pizza</span><span>Base partagée · Paiement et SMS simulés</span></footer></main></div>`;bind()}
function heading(title,sub,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="actions">${actions}</div></div>`}function stat(title,value,note,cls='',icon='◷'){return `<div class="stat"><div class="stat-top"><span>${title}</span><span>${icon}</span></div><div class="stat-value">${value}</div><small class="${cls}">${note}</small></div>`}function capacityPanel(){return `<section class="panel"><div class="panelhead"><div><h2>Capacité des prochains créneaux</h2><p class="muted">${state.capacity} pizzas maximum / 10 minutes</p></div><button class="textbtn" data-nav="capacity">Ajuster ↗</button></div><div class="capacity">${state.slots.map(t=>{let n=load(t),p=Math.min(100,Math.round(n/state.capacity*100));return `<div class="slotcolumn"><div class="bararea"><div class="barfill ${p>=100?'full':p>70?'busy':''}" style="height:${Math.max(p,4)}%"></div><span class="barvalue">${n}/${state.capacity}</span></div><div class="time">${clock(t)}</div></div>`}).join('')}</div><div class="legend"><span><i></i>Disponible</span><span><i style="background:#f4aa54"></i>Forte affluence</span><span><i style="background:#ec694a"></i>Complet</span></div></section>`}function service(){return `<section class="panel service"><h2>Le service, sous contrôle.</h2><p class="muted">${paused()?`Prise de commandes suspendue jusqu’à ${clock(state.pausedUntil)}`:'Les commandes en ligne sont ouvertes.'}</p><div class="service-row"><span>Cadence théorique</span><strong>${state.capacity*6}<small style="margin:0;text-align:right">pizzas / heure</small></strong></div><hr><div class="service-row"><span>Prochain retrait</span><b>${clock(state.slots.find(t=>t>Date.now()&&load(t)<state.capacity)||state.slots[7])}</b></div><button class="${paused()?'dark':'primary'}" data-action="panic">${paused()?'Reprendre les commandes':'Ⅱ  Mettre le service en pause'}</button><small>Un imprévu ? Prenez le temps de souffler.</small></section>`}function alerts(){const low=Object.values(state.stock).filter(s=>s.qty<=s.alert);return `<section class="panel"><div class="panelhead"><h2>À surveiller <span class="badge PREPARING">${low.length}</span></h2></div><div class="stock-alert">${low.length?low.map(s=>`<div class="ingredient"><div class="ingredient-title"><span class="bullet">!</span><div>${s.name}<small>${s.qty===0?'Rupture de stock':'Stock faible'}</small></div></div><b>${s.qty} <small>${s.unit}</small></b></div>`).join(''):'<p class="muted">Tous les stocks sont suffisants.</p>'}<button class="textbtn" data-nav="stock" style="margin:16px 0">Gérer les stocks →</button></div></section>`}function orderTable(limit=99){let list=state.orders.filter(o=>filter==='all'||o.status===filter).sort((a,b)=>a.slot-b.slot).slice(0,limit);return `<div class="tablewrap"><table><thead><tr><th>COMMANDE</th><th>CLIENT</th><th>RETRAIT</th><th>STATUT</th><th>TOTAL</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><b>#${o.id}</b><small>${qty(o.items)} pizzas</small></td><td>${esc(o.name)}<small>${esc(itemtext(o.items))}</small></td><td><b>${clock(o.slot+(o.delay||0))}</b>${o.delay?'<small>Retard annoncé +'+o.delay/60000+' min</small>':''}</td><td>${badge(o)}</td><td>${money(total(o.items))}</td><td><button aria-label="Détails de la commande ${o.id}" data-detail="${o.id}" style="border:0">↗</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">Aucune commande dans cette catégorie.</div>'}</div>`}function orderPanel(limit){return `<section class="panel"><div class="panelhead"><h2>Les commandes du service</h2><button class="textbtn" data-nav="orders">Tout voir ↗</button></div><div class="tabs">${[['all','Toutes'],['QUEUED','À préparer'],['PREPARING','En cours'],['READY','Prêtes']].map(([id,t])=>`<button data-filter="${id}" class="${filter===id?'selected':''}">${t}</button>`).join('')}</div>${orderTable(limit)}</section>`}
function dashboard(){const paid=state.orders.filter(o=>o.status!=='CANCELLED');return heading('Vue d’ensemble','Tout ce qu’il faut pour un service qui roule.',`<button data-nav="client">↗ Voir la boutique</button><button class="dark" data-nav="kitchen">♨ Ouvrir la cuisine</button>`)+`<div class="stats">${stat('Commandes du service',paid.length,'Enregistrées dans la base partagée','','▤')}${stat('Pizzas à produire',paid.filter(o=>['QUEUED','PREPARING','BAKING'].includes(o.status)).reduce((n,o)=>n+qty(o.items),0),'Dans la file de production','good','♨')}${stat('Chiffre d’affaires',money(paid.reduce((n,o)=>n+total(o.items),0)),'Commandes validées uniquement','good','€')}${stat('Commandes prêtes',paid.filter(o=>o.status==='READY').length,'En attente de retrait au comptoir','warn','✓')}</div><div class="grid"><div class="stack">${capacityPanel()}${orderPanel(5)}</div><div class="stack">${service()}${alerts()}</div></div>`}function ordersView(){return heading('Commandes','Du panier au comptoir, chaque commande à sa place.',`<button class="primary" data-nav="client">+ Nouvelle commande</button>`)+orderPanel(999)+`<section class="panel" style="margin-top:24px"><div class="panelhead"><h2>Notifications simulées</h2></div>${state.notifications.length?state.notifications.slice(-8).reverse().map(n=>`<div class="notification">${esc(n.text)}<small>${clock(n.at)} · Simulation, aucun SMS envoyé</small></div>`).join(''):'<div class="empty">Les notifications de retrait et de retard apparaîtront ici.</div>'}</section>`}
function kitchen(){return heading('La cuisine','Les étapes avancent uniquement avec vos validations.',`<span class="badge">${clock(Date.now())} · Cuisson indicative : 7 min</span>`)+`<div class="board">${['QUEUED','PREPARING','BAKING','READY'].map(status=>{let list=state.orders.filter(o=>o.status===status&&(status!=='QUEUED'||o.slot+(o.delay||0)-12*60000<=Date.now())).sort((a,b)=>(a.slot+(a.delay||0))-(b.slot+(b.delay||0)));return `<section class="board-col"><h2>${names[status]} <span class="badge">${list.length}</span></h2>${list.map(o=>`<article class="ordercard"><h3>#${o.id}<span>${clock(o.slot+(o.delay||0))}</span></h3><p>${esc(o.name)}</p><p>${recipes.filter(r=>o.items[r.id]).map(r=>`<b>${o.items[r.id]}×</b> ${r.name}`).join('<br>')}</p>${status==='BAKING'?`<small>Au four depuis ${Math.max(0,Math.floor((Date.now()-o.bakedAt)/60000))} min · indicatif</small>`:''}${o.delay?`<small class="late">Retrait décalé de ${o.delay/60000} min</small>`:''}<button class="${status==='READY'?'dark':'primary'}" data-advance="${o.id}">${{QUEUED:'Commencer',PREPARING:'Enfourné',BAKING:'Prête / Emballée',READY:'Retirée au comptoir'}[status]}</button>${status!=='READY'?`<button data-delay="${o.id}">+5 min de retard</button>`:''}</article>`).join('')||'<div class="empty">Tout est à jour.</div>'}</section>`}).join('')}</div><p class="muted">${state.orders.filter(o=>o.status==='QUEUED'&&o.slot+(o.delay||0)-12*60000>Date.now()).length} commande(s) planifiée(s) apparaîtront 12 minutes avant le retrait.</p>`}
function stocks(){return heading('Stocks & recettes','Les disponibilités de la boutique suivent vos ingrédients.')+`<section class="panel"><div class="panelhead"><h2>Réserve d’ingrédients</h2><span class="muted">Déduits à la validation du paiement</span></div><div class="tablewrap"><table class="stocktable"><thead><tr><th>INGRÉDIENT</th><th>STOCK PHYSIQUE</th><th>RÉSERVÉ</th><th>SEUIL D’ALERTE</th><th>AJUSTER</th><th></th></tr></thead><tbody>${Object.entries(state.stock).map(([id,s])=>`<tr><td><b>${s.name}</b></td><td>${s.qty} ${s.unit} ${s.qty<=s.alert?'<span class="badge PREPARING">'+(s.qty===0?'Rupture':'Faible')+'</span>':''}</td><td>${held()?(need(state.hold.items)[id]||0):0}</td><td>${s.alert} ${s.unit}</td><td><input type="number" min="0" step="1" aria-label="Stock ${s.name}" value="${s.qty}" id="stock-${id}"> <button data-stock="${id}">Enregistrer</button></td><td><button class="danger" data-rupture="${id}">Rupture</button></td></tr>`).join('')}</tbody></table></div></section><h2 style="margin:28px 0 18px">Fiches recettes · composition par pizza</h2><div class="menu-grid">${recipes.map(r=>`<section class="panel pizza"><h3>${r.name}</h3><p>${Object.entries(r.bom).map(([id,n])=>`${state.stock[id].name} : ${n} ${state.stock[id].unit}`).join(' · ')}</p><span class="badge ${enough({[r.id]:1})?'READY':'CANCELLED'}">${enough({[r.id]:1})?'Disponible en boutique':'Épuisée'}</span><strong style="float:right">${money(r.price)}</strong></section>`).join('')}</div>`}
function capacityView(){return heading('Capacité & service','Ajustez la cadence à la réalité de votre cuisine.')+`<div class="grid"><div class="stack">${capacityPanel()}<section class="panel" style="padding:24px"><h2>Cadence de production</h2><p class="muted">Le quota s’applique aux créneaux de 10 minutes. Les commandes déjà validées restent honorées.</p><label class="field">Pizzas par créneau<input id="capacity" type="number" min="1" max="200" value="${state.capacity}"></label><button class="dark" data-action="saveCapacity">Enregistrer la capacité</button><p class="muted">Préparation : 5 min · Cuisson : 7 min · Réservation panier : 5 min</p></section></div><div class="stack">${service()}<section class="panel" style="padding:22px"><h2>Données partagées</h2><p class="muted">Les commandes et les stocks sont enregistrés sur le serveur et partagés entre vos appareils. Paiement et notifications restent simulés.</p><span class="badge READY">Sauvegarde côté serveur</span></section></div></div>`}
function client(){const sum=qty(cart);return heading('La carte','Votre pizza préférée. Prête à l’heure choisie.')+`${paused()?`<p class="badge CANCELLED">La prise de commandes est suspendue jusqu’à ${clock(state.pausedUntil)}.</p>`:''}<div class="menu-banner"><div><h2>La bonne pizza.<br>Sans attendre à table.</h2><p>Faite sur place, à emporter.</p></div><img src="pizza.jpg" alt="Pizza fraîchement cuite"></div><div class="menu-layout"><div><div class="menu-grid">${recipes.map(r=>{const available=enough({[r.id]:1});return `<article class="panel pizza"><span class="muted">${r.tag}</span><h3>${r.name}</h3><p>${r.desc}</p><div class="pizza-bottom"><strong>${money(r.price)}</strong><button class="${available?'primary':''}" data-add="${r.id}" ${!available?'disabled':''}>${available?'+ Ajouter':'Épuisée'}</button></div></article>`}).join('')}</div>${state.orders.filter(o=>o.client).reverse().map(o=>`<section class="panel tracking"><h2>Votre commande #${o.id}</h2><p class="muted">${esc(itemtext(o.items))} · Retrait à ${clock(o.slot+(o.delay||0))}</p>${badge(o)}<div class="tracksteps">${['Confirmée','En préparation','Prête au comptoir','Retirée'].map((s,i)=>`<span class="${({QUEUED:0,PREPARING:1,BAKING:1,READY:2,COLLECTED:3}[o.status]??-1)>=i?'done':''}">${s}</span>`).join('')}</div></section>`).join('')}</div><aside class="panel cart"><h2>Votre panier <span class="badge">${sum}</span></h2>${sum?recipes.filter(r=>cart[r.id]).map(r=>`<div class="cartline"><div>${r.name}<br><small>${money(r.price*cart[r.id])}</small></div><div class="stepper"><button data-minus="${r.id}" aria-label="Retirer une ${r.name}">−</button>${cart[r.id]}<button data-add="${r.id}" aria-label="Ajouter une ${r.name}">+</button></div></div>`).join(''):'<p class="muted">Choisissez vos pizzas pour commencer.</p>'}<h3 style="margin-top:23px">Votre heure de retrait</h3><div class="slots">${state.slots.map((t,i)=>`<button class="${selected===i?'selected':''}" data-slot="${i}" ${load(t)+sum>state.capacity||t<Date.now()+12*60000?'disabled':''}>${clock(t)}</button>`).join('')}</div><div class="cartline" style="border:0;margin-bottom:14px"><b>Total</b><b>${money(total(cart))}</b></div><button class="primary fullwidth" data-action="checkout" ${!sum||paused()?'disabled':''}>Réserver et payer →</button><p class="prototype">Paiement de démonstration · Aucun débit réel</p>${held()?'<button class="fullwidth" data-action="resume">Reprendre le paiement réservé</button>':''}</aside></div>`}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]());document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const next={...cart,[b.dataset.add]:(cart[b.dataset.add]||0)+1};if(!enough(next))return toast('Stock insuffisant pour cette quantité.');cart=next;render()});document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{if(--cart[b.dataset.minus]<=0)delete cart[b.dataset.minus];render()});document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{selected=+b.dataset.slot;render()});document.querySelectorAll('[data-advance]').forEach(b=>b.onclick=()=>advance(+b.dataset.advance));document.querySelectorAll('[data-delay]').forEach(b=>b.onclick=()=>delay(+b.dataset.delay));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(+b.dataset.detail));document.querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>{let n=+$('#stock-'+b.dataset.stock).value;if(!Number.isInteger(n)||n<0)return toast('Indiquez une quantité entière positive ou nulle.');state.stock[b.dataset.stock].qty=n;save();render();toast('Stock mis à jour, disponibilités recalculées.');});document.querySelectorAll('[data-rupture]').forEach(b=>b.onclick=()=>{state.stock[b.dataset.rupture].qty=0;save();render();toast('Ingrédient en rupture : recettes associées désactivées.');})}
function modal(html){$('#modal').innerHTML='<button class="close" aria-label="Fermer" onclick="document.querySelector(\'#modal\').close()">×</button>'+html;$('#modal').showModal()}function notify(text){state.notifications.push({at:Date.now(),text})}function advance(id){const o=state.orders.find(o=>o.id===id),next={QUEUED:'PREPARING',PREPARING:'BAKING',BAKING:'READY',READY:'COLLECTED'}[o?.status];if(!next)return; o.status=next;if(next==='BAKING')o.bakedAt=Date.now();if(next==='READY')notify(`Commande #${o.id} : votre commande est prête au comptoir !`);save();render();toast(next==='READY'?'Commande prête · notification client simulée':`Commande #${id} · ${names[next]}`)}function delay(id){const o=state.orders.find(o=>o.id===id);o.delay=(o.delay||0)+300000;notify(`Commande #${id} : retrait estimé à ${clock(o.slot+o.delay)} (+5 min).`);save();render();toast('Estimation décalée de 5 min · notification simulée.')}function detail(id){const o=state.orders.find(o=>o.id===id);modal(`<h2>Commande #${id}</h2><p>${esc(o.name)} · Retrait à ${clock(o.slot+(o.delay||0))}</p>${badge(o)}<p>${esc(itemtext(o.items))}</p><b>${money(total(o.items))}</b>${!['COLLECTED','CANCELLED'].includes(o.status)?`<div class="modal-actions"><button class="danger" id="cancelorder">Annuler la commande</button></div>`:''}`);if($('#cancelorder'))$('#cancelorder').onclick=()=>{if(['PREPARING','BAKING','READY'].includes(o.status)){o.status='CANCELLED'}else{Object.entries(need(o.items)).forEach(([k,n])=>state.stock[k].qty+=n);o.status='CANCELLED'}notify(`Commande #${id} annulée. Remboursement simulé.`);save();$('#modal').close();render();toast('Commande annulée · remboursement simulé.')}}
const actions={panic(){if(paused()){state.pausedUntil=0;save();render();return toast('Les commandes sont à nouveau ouvertes.')}modal('<h2>Une pause pour la cuisine</h2><p class="muted">Les commandes en cours restent affichées. Les nouvelles commandes sont bloquées pendant la durée choisie.</p><div class="modal-actions">'+[15,30,60].map(n=>`<button class="danger" data-pause="${n}">${n} min</button>`).join('')+'</div>');document.querySelectorAll('[data-pause]').forEach(b=>b.onclick=()=>{state.pausedUntil=Date.now()+(+b.dataset.pause)*60000;save();$('#modal').close();render();toast('Prise de commandes mise en pause.');})},saveCapacity(){const n=+$('#capacity').value;if(!Number.isInteger(n)||n<1||n>200)return toast('Choisissez entre 1 et 200 pizzas par créneau.');state.capacity=n;save();render();toast('La capacité des créneaux a été mise à jour.')},reset(){modal('<h2>Réinitialiser la démo ?</h2><p>Les commandes et modifications de ce navigateur seront remplacées par les exemples initiaux.</p><div class="modal-actions"><button onclick="document.querySelector(\'#modal\').close()">Conserver</button><button class="danger" id="confirmreset">Réinitialiser</button></div>');$('#confirmreset').onclick=()=>{state=initial();cart={};selected=0;save();$('#modal').close();render()}},checkout(){expire();if(held())return payment();if(paused()||!qty(cart))return toast('La commande ne peut pas être réservée.');if(!enough(cart))return toast('Un ingrédient est indisponible. Modifiez votre panier.');const slot=state.slots[selected];if(slot<Date.now()+12*60000||load(slot)+qty(cart)>state.capacity){const next=state.slots.findIndex(t=>t>=Date.now()+12*60000&&load(t)+qty(cart)<=state.capacity);if(next>=0)selected=next;render();return toast('Créneau indisponible. Le prochain créneau possible a été sélectionné.');}state.hold={items:{...cart},slot,expires:Date.now()+300000};save();render();payment()},resume(){payment()}};
function payment(){if(!held())return toast('Cette réservation a expiré.');modal(`<h2>Votre table ? Chez vous.</h2><p class="muted">Retrait à ${clock(state.hold.slot)} · ${qty(state.hold.items)} pizzas</p><p>Panier réservé pendant <b id="countdown"></b></p><label class="field">Votre prénom<input id="customer" maxlength="60" placeholder="Ex. Camille" autocomplete="given-name"></label><p class="prototype">Simulation : aucune carte bancaire demandée et aucun paiement réel.</p><div class="modal-actions"><button id="failpay">Annuler</button><button class="primary" id="pay">Valider ${money(total(state.hold.items))}</button></div>`);tick();$('#failpay').onclick=()=>{state.hold=null;save();$('#modal').close();render();toast('Réservation annulée, stocks et capacité libérés.')};$('#pay').onclick=()=>{const name=$('#customer').value.trim();if(!name)return toast('Indiquez votre prénom pour le retrait.');expire();if(!held())return;if(!enough(state.hold.items,false)){state.hold=null;save();$('#modal').close();render();return toast('Un ingrédient est passé en rupture. Réservation libérée.');}const h=state.hold;Object.entries(need(h.items)).forEach(([id,n])=>state.stock[id].qty-=n);const id=state.next++;state.orders.push({id,name,items:h.items,slot:h.slot,status:'QUEUED',client:true});state.hold=null;cart={};save();$('#modal').close();render();toast(`Commande #${id} confirmée. Retrouvez son suivi sous la carte.`)}}function tick(){expire();if($('#countdown')&&held()){let s=Math.max(0,Math.ceil((state.hold.expires-Date.now())/1000));$('#countdown').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}}if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_service_overview',title:'Consulter le service',description:'Consulter les commandes, les capacités et les stocks reçus du serveur.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Aucun paramètre attendu');return{orders:state.orders,capacity:state.capacity,paused:paused(),stock:state.stock}}})}catch{}}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
